PY
cat > src/orchestration/tools/registry.dynamic.test.ts <<'EOF'
import {ToolRegistry} from './registry.js';

describe('ToolRegistry dynamic schemas [specs/hal-engine-tool-input-validation/spec.md#7]', () => {
  it('validates the current dynamic schema', async () => {
    const registry = new ToolRegistry();
    let required = 'first';
    registry.register(
      () => ({name: 'dynamic', description: 'Dynamic', inputSchema: {type: 'object', required: [required]}}),
      async () => 'executed'
    );
    const first = await registry.execute('dynamic', {first: 'yes'});
    required = 'second';
    const second = await registry.execute('dynamic', {first: 'yes'});
    expect({first: first.result, second: second.result}).toEqual({
      first: 'executed',
      second: expect.stringMatching(/second.*required|required.*second/i),
    });
  });
});
EOF
 timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/tools/registry.dynamic.test.ts"
